BEGIN;

-- Prosa que acompana a 20260908009900_casandra_soberano_epochs.sql.
--
-- La correccion de epocas deja mal dos frases escritas antes de saberlo:
--
--   joseito-mateo  llamaba "Gran Soberano" a lo que en 2004 se llamaba "El
--     Soberano". El nombre de la maxima distincion de ACROARTE cambio en 2013,
--     cuando los premios pasaron de Casandra a Soberano: hasta 2012 la regular
--     era el Casandra y la maxima El Soberano; desde 2013 la regular es el
--     Soberano y la maxima El Gran Soberano.
--
--     El titular de Hoy del 23 de marzo de 2004 lo dice sin margen: "Joseito
--     Mateo gana El Soberano de los premios Casandra".
--
--     La frase no se limita a corregir el nombre: explica el cambio, porque un
--     lector que busque "Gran Soberano 2004" no lo va a encontrar.
--
--   felix-del-rosario  decia "Recibio un Casandra especial", sin fecha, porque
--     cuando se escribio la ficha no habia fuente que la diera. Ahora la hay:
--     **1996**, segun la nota necrologica de la propia ACROARTE del 27 de
--     octubre de 2012, repetida por El Dia, El Caribe y Hoy. El Caribe anade el
--     motivo: "por su trayectoria".
--
--     De paso se ordenan los dos reconocimientos por fecha, que estaban al
--     reves, y se escribe Casandra Especial en mayusculas, que es el nombre de
--     la categoria.
--
-- PARA REVERTIR: supabase/rollback/20260908010000_revert_casandra_soberano_prose.sql
--
-- Aplicado directamente por DATABASE_URL. No corrio ninguna funcion de Vercel
-- y no se revalido nada.

-- joseito-mateo [es]
UPDATE editorial_documents SET document = '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"José Tamárez Mateo, conocido como Joseíto Mateo y llamado El Rey del Merengue, fue un cantante dominicano. Empezó a presentarse en los años treinta y seguía trabajando al final de su vida, lo que le dio una carrera de más de setenta años y lo convirtió en la presencia continua más larga de la música popular dominicana.","type":"text"}]},{"type":"paragraph","content":[{"text":"Santo Domingo y La Habana","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Nació en Santo Domingo en 1920 y empezó a cantar de joven, ganando público a lo largo de los treinta y los cuarenta. En uno de sus viajes a Cuba se quedó a cantar en la CMQ, entonces la emisora más grande de la isla, junto a Celia Cruz y la Sonora Matancera, justo cuando la radio cubana fijaba las reglas para todo el Caribe.","type":"text"}]},{"type":"paragraph","content":[{"text":"El Gran Combo","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Tras el ajusticiamiento de Trujillo en 1961 se fue a probar suerte a Puerto Rico, y en 1962 cantó con El Gran Combo en la primera gira del grupo a Panamá, promocionando el disco El Gran Combo con Joseíto Mateo. Se adaptó a su repertorio, cantando plena, bomba, guaracha y bolero, y en ese viaje conoció a los jóvenes Pellín Rodríguez y Andy Montañez, que terminaron ocupando su lugar en la orquesta.","type":"text"}]},{"type":"paragraph","content":[{"text":"La razón de su salida la dio él mismo sin rodeos. Tuvo que volver a Santo Domingo a limpiar su nombre: en los años posteriores a la dictadura se perseguía a quien hubiera trabajado bajo ella, y mientras él cantaba afuera en el país lo llamaban espía.","type":"text"}]},{"type":"paragraph","content":[{"text":"Las canciones","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Su catálogo es enorme y empezó temprano. King of Merengue! salió en 1950 y Merenchanga Pa’ la Pachanga en 1956, y a lo largo de los sesenta publicó disco tras disco: El Verdadero Rey del Merengue en 1964, Caña Brava Vol. 3 y Merengues Vol. 2 en 1966, Salsa Explosiva en 1970.","type":"text"}]},{"type":"paragraph","content":[{"text":"Las canciones que quedaron son Madame Chuchí, Dame la Visa, La Cotorra de Rosa, La Patrulla, Juanita Morel y Merenguero Hasta la Tambora. En 1979 hizo un disco de merengues con ","type":"text"},{"type":"artistReference","attrs":{"artistId":"dab6636c-21fd-4e34-a0a2-e59e9e147bbd","displayText":"Luis Kalaff","occurrenceId":"1f023583-ad08-4f83-a554-c5022288530c"}},{"text":", de quien además había grabado Cuando Yo Me Muera.","type":"text"}]},{"type":"paragraph","content":[{"text":"El baile","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Lo que lo separaba no era solo la voz. Cantaba bailando, y su manera de moverse en tarima pasó a formar parte de cómo se veía el merengue y no solo de cómo sonaba, justo cuando el género salía de los conjuntos de campo hacia los salones de baile y los estudios de televisión.","type":"text"}]},{"type":"paragraph","content":[{"text":"Los reconocimientos","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Acroarte le dio El Soberano en 2004, entonces su máximo galardón y el que desde 2013 se llama Gran Soberano, y el 11 de noviembre de 2010 la Academia Latina de la Grabación le entregó el Premio a la Excelencia Musical por su aporte a la música latina.","type":"text"}]},{"type":"paragraph","content":[{"text":"Murió en 2018, a los noventa y ocho años. En su velatorio ","type":"text"},{"type":"artistReference","attrs":{"artistId":"73691e65-206a-4c71-9b5f-8689f15b2584","displayText":"Cheché Abreu","occurrenceId":"05db25ef-26b3-40d2-bea7-6030ff74d410"}},{"text":" dijo que Joseíto había sido el más grande porque de él lo copiaron todo los demás, y que para el país no iba a morirse nunca.","type":"text"}]}]}'::jsonb WHERE id = '6413dd84-18bc-46a6-9a91-ef98a9fe5fea';

-- joseito-mateo [en]
UPDATE editorial_documents SET document = '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"José Tamárez Mateo, known as Joseíto Mateo and called the King of Merengue, was a Dominican singer. He began performing in the nineteen-thirties and was still working at the end of his life, which gave him a career of more than seventy years and made him the longest continuous presence in Dominican popular music.","type":"text"}]},{"type":"paragraph","content":[{"text":"Santo Domingo and Havana","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"He was born in Santo Domingo in 1920 and started singing as a young man, building an audience through the thirties and forties. On one of his trips to Cuba he stayed on to sing at CMQ, then the largest station on the island, alongside Celia Cruz and the Sonora Matancera, at the point when Cuban radio was setting the terms for the whole Caribbean.","type":"text"}]},{"type":"paragraph","content":[{"text":"El Gran Combo","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"After the killing of Trujillo in 1961 he went to try his luck in Puerto Rico, and in 1962 he sang with El Gran Combo on the group’s first tour to Panama, promoting the album El Gran Combo con Joseíto Mateo. He adapted to their repertoire, singing plena, bomba, guaracha and bolero, and it was on that trip that he met the young Pellín Rodríguez and Andy Montañez, who took his place in the band.","type":"text"}]},{"type":"paragraph","content":[{"text":"He gave a plain reason for leaving. He had to go back to Santo Domingo to clear his name: in the years after the dictatorship anyone who had worked under it was being pursued, and he was being called a spy at home while he was singing abroad.","type":"text"}]},{"type":"paragraph","content":[{"text":"The songs","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"His catalogue is enormous and began early. King of Merengue! appeared in 1950 and Merenchanga Pa’ la Pachanga in 1956, and through the sixties he released album after album — El Verdadero Rey del Merengue in 1964, Caña Brava Vol. 3 and Merengues Vol. 2 in 1966, Salsa Explosiva in 1970.","type":"text"}]},{"type":"paragraph","content":[{"text":"The songs that stayed are Madame Chuchí, Dame la Visa, La Cotorra de Rosa, La Patrulla, Juanita Morel and Merenguero Hasta la Tambora. In 1979 he made an album of merengues with ","type":"text"},{"type":"artistReference","attrs":{"artistId":"dab6636c-21fd-4e34-a0a2-e59e9e147bbd","displayText":"Luis Kalaff","occurrenceId":"a6d3b2a2-2617-4e18-a755-38395aa53c8f"}},{"text":", whose Cuando Yo Me Muera he had also recorded.","type":"text"}]},{"type":"paragraph","content":[{"text":"The dancing","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"What separated him was not only the voice. He sang while dancing, and the way he moved on stage became part of what merengue looked like as well as what it sounded like, at a moment when the genre was moving from country ensembles into ballrooms and television studios.","type":"text"}]},{"type":"paragraph","content":[{"text":"The honours","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Acroarte gave him El Soberano in 2004, its highest award at the time and the one renamed Gran Soberano in 2013, and on 11 November 2010 the Latin Recording Academy presented him with its Musical Excellence Award for his contribution to Latin music.","type":"text"}]},{"type":"paragraph","content":[{"text":"He died in 2018, at ninety-eight. At his wake ","type":"text"},{"type":"artistReference","attrs":{"artistId":"73691e65-206a-4c71-9b5f-8689f15b2584","displayText":"Cheché Abreu","occurrenceId":"6a5a5bcc-0754-4f41-b420-258fec9c6a1d"}},{"text":" said that Joseíto had been the greatest because everything the rest of them did was copied from him, and that he would never really be dead for the country.","type":"text"}]}]}'::jsonb WHERE id = '5e639bfa-a309-4323-af22-4b306db16e74';

-- felix-del-rosario [es]
UPDATE editorial_documents SET document = '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Félix del Rosario fue un saxofonista, compositor y director de orquesta dominicano. Dirigió Félix del Rosario y Sus Magos del Ritmo durante más de veinte años, y cambió la manera de escribir para las orquestas de merengue: redujo la sección de metales a dos saxofones y metió el jazz afrocubano en una música que no se había escrito así. Murió en Santo Domingo el 26 de octubre de 2012, a los setenta y ocho.","type":"text"}]},{"type":"paragraph","content":[{"text":"La banda de la Marina","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Nació el 12 de julio de 1934 en San Francisco de Macorís y empezó a estudiar a los quince en la escuela municipal de música de la ciudad. Todavía joven se fue a la capital —entonces Ciudad Trujillo— y entró en la Banda de la Marina de Guerra, donde llegó a oficial. El jazz se le metió dentro en esos años.","type":"text"}]},{"type":"paragraph","content":[{"text":"En 1953 entró en la orquesta de Antonio Morel, y después trabajó con Amado Vásquez, Agustín Mercier y ","type":"text"},{"type":"artistReference","attrs":{"artistId":"ba42e200-51b0-437b-99ac-1daf39ade337","displayText":"Rafael Solano","occurrenceId":"9cd8244e-7e8d-43f7-b50d-da788aa65ff5"}},{"text":".","type":"text"}]},{"type":"paragraph","content":[{"text":"Dos saxofones","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"La orquesta bailable dominicana de la época llevaba dos saxofones, dos trompetas y un trombón. Del Rosario lo redujo a dos saxofones y nada más, alternando alto, barítono y tenor y añadiendo flauta, lo que le dio a sus discos un frente más liviano y más móvil que el de las orquestas de alrededor.","type":"text"}]},{"type":"paragraph","content":[{"text":"Lo que puso en el sitio que había despejado fue jazz. Su manera de tocar viene de la bossa nova y del jazz afrocubano, y escribía para sí mismo como solista improvisador y no como jefe de sección. Carmen, una guaracha cruzada con jazz latino, es el caso más claro.","type":"text"}]},{"type":"paragraph","content":[{"text":"Los Magos del Ritmo","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Formó Félix del Rosario y Sus Magos del Ritmo en 1964, y la orquesta se mantuvo en primera línea de la música popular dominicana más de dos décadas. Tocaron en ella Antonio Peña, Papito Bazán, Quico Marcano y Manuel Perdomo, y cantaron ","type":"text"},{"type":"artistReference","attrs":{"artistId":"2cb00350-16da-41b4-bec9-5c86b5d8438c","displayText":"Frank Cruz","occurrenceId":"7d3ca4c3-3735-4622-8b8b-12bec0435bbe"}},{"text":" y El Negrito Macabí. Más adelante armó la Santo Domingo All Star y el Grupo Félix.","type":"text"}]},{"type":"paragraph","content":[{"text":"Los merengues que quedaron en el repertorio son Papá Bocó, que le escribió ","type":"text"},{"type":"artistReference","attrs":{"artistId":"9f62f1e7-2aad-4690-8451-82df4dd3b587","displayText":"Manuel Sánchez Acosta","occurrenceId":"f4624907-ef74-4a40-b50d-0c6834ef579a"}},{"text":", junto a Víctor y Memelo, Mal Pelao, La Caperucita y El Secuestro.","type":"text"}]},{"type":"paragraph","content":[{"text":"La Navidad","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Una parte grande de su catálogo es música de Navidad, y llama la atención por el tamaño de la apuesta: entre 1968 y 1994 publicó seis discos —Parrandas Navideñas en Ritmo de Merengue, dos volúmenes de Éxitos Navideños, El Tren de la Navidad, Félix Navidad y Navidad Criolla—, todos ellos repertorio navideño arreglado como merengue.","type":"text"}]},{"type":"paragraph","content":[{"text":"Distinciones","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"San Francisco de Macorís lo declaró hijo meritorio de la ciudad en 1973. En 1995 el Gobierno dominicano le concedió la Orden del Mérito de Duarte, Sánchez y Mella, y al año siguiente Acroarte le entregó un Casandra Especial por su trayectoria.","type":"text"}]}]}'::jsonb WHERE id = '693ad3b0-fd77-467f-b6d4-7a0bb89edb21';

-- felix-del-rosario [en]
UPDATE editorial_documents SET document = '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Félix del Rosario was a Dominican saxophonist, composer and bandleader. He led Félix del Rosario y Sus Magos del Ritmo for more than twenty years, and he changed the way merengue bands were scored: he cut the horn section down to two saxophones and brought Afro-Cuban jazz into a music that had not been written that way before. He died in Santo Domingo on 26 October 2012, at seventy-eight.","type":"text"}]},{"type":"paragraph","content":[{"text":"The navy band","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"He was born on 12 July 1934 in San Francisco de Macorís and began studying at fifteen at the municipal music school there. Still young, he moved to the capital — Ciudad Trujillo at the time — and joined the band of the Navy, where he rose to the rank of officer. Jazz took hold of him during those years.","type":"text"}]},{"type":"paragraph","content":[{"text":"In 1953 he joined the orchestra of Antonio Morel, and afterwards worked with Amado Vásquez, Agustín Mercier and ","type":"text"},{"type":"artistReference","attrs":{"artistId":"ba42e200-51b0-437b-99ac-1daf39ade337","displayText":"Rafael Solano","occurrenceId":"149d6fb3-e83c-42b0-8fd0-a17675fbbdc9"}},{"text":".","type":"text"}]},{"type":"paragraph","content":[{"text":"Two saxophones","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"The standard Dominican dance band of the period carried two saxophones, two trumpets and a trombone. Del Rosario reduced that to two saxophones and nothing else, alternating alto, baritone and tenor and adding flute, which gave his records a lighter and more mobile front line than the orchestras around him.","type":"text"}]},{"type":"paragraph","content":[{"text":"What he put in the space he had cleared was jazz. His playing draws on bossa nova and on Afro-Cuban jazz, and he wrote for himself as an improvising soloist rather than as a section leader. Carmen, a guaracha crossed with Latin jazz, is the clearest case.","type":"text"}]},{"type":"paragraph","content":[{"text":"Los Magos del Ritmo","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"He formed Félix del Rosario y Sus Magos del Ritmo in 1964, and it stayed in the front rank of Dominican popular music for more than two decades. Antonio Peña, Papito Bazán, Quico Marcano and Manuel Perdomo played in it, and ","type":"text"},{"type":"artistReference","attrs":{"artistId":"2cb00350-16da-41b4-bec9-5c86b5d8438c","displayText":"Frank Cruz","occurrenceId":"8b024296-32e7-4310-8859-a091434f2e00"}},{"text":" and El Negrito Macabí sang. He later put together the Santo Domingo All Star and the Grupo Félix.","type":"text"}]},{"type":"paragraph","content":[{"text":"The merengues that stayed in the repertoire are Papá Bocó, written for him by ","type":"text"},{"type":"artistReference","attrs":{"artistId":"9f62f1e7-2aad-4690-8451-82df4dd3b587","displayText":"Manuel Sánchez Acosta","occurrenceId":"3632cf83-9fc7-4ae9-b542-5a35c946e868"}},{"text":", along with Víctor y Memelo, Mal Pelao, La Caperucita and El Secuestro.","type":"text"}]},{"type":"paragraph","content":[{"text":"Christmas","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"A large part of his catalogue is Christmas music, which is unusual in the size of the commitment: between 1968 and 1994 he released six albums of it — Parrandas Navideñas en Ritmo de Merengue, two volumes of Éxitos Navideños, El Tren de la Navidad, Félix Navidad and Navidad Criolla — all of it Christmas repertoire arranged as merengue.","type":"text"}]},{"type":"paragraph","content":[{"text":"Distinctions","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"San Francisco de Macorís named him a meritorious son of the city in 1973. The Dominican government gave him the Order of Merit of Duarte, Sánchez and Mella in 1995, and the following year Acroarte presented him with a Casandra Especial for his career.","type":"text"}]}]}'::jsonb WHERE id = '6ede8a34-5afc-4388-bf36-a5e179e60c28';

COMMIT;
